class StashStack:
    def __init__(self):
        self.stack = []

    def stash(self, branch, changes):
        entry = {"branch": branch, "changes": changes}
        self.stack.insert(0, entry)
        return f"guardado: WIP on {branch}: {changes}"

    def list(self):
        return [f"stash@{{{i}}}: WIP on {e['branch']}: {e['changes']}" for i, e in enumerate(self.stack)]

    def pop(self):
        entry = self.stack.pop(0)
        return f"restaurado y eliminado: {entry['changes']}"

    def apply(self, index=0):
        entry = self.stack[index]
        return f"restaurado sin eliminar: {entry['changes']}"


s = StashStack()
print(s.stash("master", "cambios en app.js"))
print(s.stash("develop", "actualizar dependencias"))
for line in s.list():
    print(line)
print(s.apply(0))
print(s.pop())
print(s.list())
